def config_value(text: str, key: str) -> str:
    """Return the value for `key` in `name=value` per-line config text.

    Rules:
    - Each line is `name=value`; the split happens at the first `=`.
    - Surrounding whitespace is stripped from both the name and the value.
    - Blank lines and lines whose first non-space character is `#` are ignored.
    - If the key appears more than once, the first occurrence wins.
    - If the key is absent, return an empty string.
    - The function never reads files; it works only on `text`.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return value.strip()
    return ""


def test_returns_value_for_present_key() -> None:
    assert config_value("host=localhost\nport=8080", "port") == "8080"


def test_returns_empty_string_for_absent_key() -> None:
    assert config_value("host=localhost", "port") == ""


def test_returns_empty_string_for_empty_text() -> None:
    assert config_value("", "host") == ""


def test_strips_whitespace_around_name_and_value() -> None:
    assert config_value("  host  =  localhost  \n", "host") == "localhost"


def test_split_happens_at_first_equals_sign() -> None:
    assert config_value("expr=a=b=c", "expr") == "a=b=c"


def test_ignores_comment_lines() -> None:
    text = "# host=wrong\nhost=right"
    assert config_value(text, "host") == "right"


def test_ignores_indented_comment_lines() -> None:
    text = "   # host=wrong\nhost=right"
    assert config_value(text, "host") == "right"


def test_ignores_blank_lines() -> None:
    assert config_value("\n\nname=alice\n\n", "name") == "alice"


def test_first_occurrence_wins_for_duplicate_keys() -> None:
    assert config_value("level=1\nlevel=2", "level") == "1"


def test_key_must_match_exactly() -> None:
    assert config_value("hostname=box", "host") == ""


def test_empty_value_is_returned_as_empty_string() -> None:
    assert config_value("token=\nother=x", "token") == ""
